try:
    from scipy.optimize import least_squares
    have=True
except Exception as e:
    have=False; print('no scipy',e)
if have:
    Y=dv_dt; vy=np.var(Y)
    shapes={'x^r cos v':lambda p: (x**p[0])*np.cos(v),
            'x^r sin v':lambda p: (x**p[0])*np.sin(v),
            'x^r v^q':lambda p: (x**p[0])*(v**p[1]),
            'x^r cos t':lambda p: (x**p[0])*np.cos(t),
            'x^r exp(-v)':lambda p: (x**p[0])*np.exp(-v),
            'x^r t':lambda p: (x**p[0])*t}
    for nm_,g in shapes.items():
